CREATE VIEW v_ag_database_replica_states AS (SELECT * FROM ag_database_replica_states) UNION ALL BY NAME (SELECT * FROM read_parquet('{ARCHIVE}/*_ag_database_replica_states.parquet', (union_by_name = CAST('t' AS BOOLEAN))));
