CREATE VIEW v_config_alert_log AS (SELECT *, 'live' AS "source" FROM config_alert_log) UNION ALL BY NAME (SELECT *, 'archive' AS "source" FROM read_parquet('{ARCHIVE}/*_config_alert_log.parquet', (union_by_name = CAST('t' AS BOOLEAN))) AS p WHERE (NOT EXISTS(SELECT 1 FROM dismissed_archive_alerts AS d WHERE ((d.alert_time = p.alert_time) AND (d.server_id = p.server_id) AND (d.metric_name = p.metric_name)))));
